        case 'calendar':
            $s = '<g fill="none" stroke="' . $b . '" stroke-opacity=".35" stroke-width="2">';
            $on = [2, 5, 8, 11, 15, 19, 23, 26];
            for ($i = 0; $i < 28; $i++) {
                $x = 150 + ($i % 7) * 76; $y = 50 + intdiv($i, 7) * 68;
                $hit = in_array($i, $on, true);
                $s .= '<rect x="' . $x . '" y="' . $y . '" width="62" height="54" rx="10"' . ($hit ? ' fill="' . $o . '" stroke="' . $o . '" fill-opacity=".85"' : '') . '/>';
            }
            return $head . $s . '</g><circle cx="680" cy="300" r="26" fill="#151513" stroke="' . $b . '" stroke-opacity=".3"/><path d="M670 300l8 8 14-16" fill="none" stroke="' . $o . '" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
        case 'brand':
            return $head . '<circle cx="330" cy="180" r="100" fill="' . $o . '" fill-opacity=".9"/><circle cx="430" cy="180" r="100" fill="' . $b . '" fill-opacity=".85" style="mix-blend-mode:normal"/><circle cx="530" cy="180" r="100" fill="#1C1C19" stroke="' . $b . '" stroke-opacity=".5" stroke-width="2"/><text x="530" y="205" text-anchor="middle" font-family="Archivo, sans-serif" font-weight="800" font-size="76" fill="' . $b . '">Aa</text><polygon points="296,150 372,150 352,172 276,172" fill="#0B0B0A"/><polygon points="316,180 346,180 314,212 284,212" fill="#0B0B0A"/></svg>';
        case 'web':
            return $head . '<rect x="190" y="50" width="460" height="260" rx="18" fill="#151513" stroke="' . $b . '" stroke-opacity=".4" stroke-width="2"/><path d="M190 90h460" stroke="' . $b . '" stroke-opacity=".25" stroke-width="2"/><circle cx="216" cy="70" r="5" fill="' . $o . '"/><circle cx="236" cy="70" r="5" fill="' . $b . '" fill-opacity=".4"/><circle cx="256" cy="70" r="5" fill="' . $b . '" fill-opacity=".4"/><rect x="226" y="120" width="250" height="20" rx="6" fill="' . $b . '" fill-opacity=".85"/><rect x="226" y="152" width="190" height="12" rx="6" fill="' . $b . '" fill-opacity=".35"/><rect x="226" y="176" width="160" height="12" rx="6" fill="' . $b . '" fill-opacity=".35"/><rect x="226" y="214" width="130" height="38" rx="19" fill="' . $o . '"/><rect x="500" y="120" width="110" height="132" rx="12" fill="' . $o . '" fill-opacity=".25" stroke="' . $o . '" stroke-width="2"/><rect x="620" y="150" width="60" height="150" rx="12" fill="#0B0B0A" stroke="' . $b . '" stroke-opacity=".6" stroke-width="2"/><rect x="632" y="168" width="36" height="8" rx="4" fill="' . $b . '" fill-opacity=".6"/><rect x="632" y="262" width="36" height="16" rx="8" fill="' . $o . '"/></svg>';
        case 'wallet':
            return $head . '<rect x="320" y="24" width="200" height="320" rx="30" fill="#0B0B0A" stroke="' . $b . '" stroke-opacity=".6" stroke-width="3"/><rect x="342" y="62" width="156" height="96" rx="14" fill="' . $o . '"/><g fill="#0B0B0A" fill-opacity=".85"><circle cx="372" cy="124" r="9"/><circle cx="402" cy="124" r="9"/><circle cx="432" cy="124" r="9"/></g><g fill="none" stroke="#0B0B0A" stroke-opacity=".6" stroke-width="2.5"><circle cx="462" cy="124" r="9"/></g><rect x="342" y="178" width="156" height="14" rx="7" fill="' . $b . '" fill-opacity=".3"/><rect x="342" y="204" width="110" height="14" rx="7" fill="' . $b . '" fill-opacity=".2"/><rect x="342" y="244" width="156" height="14" rx="7" fill="' . $b . '" fill-opacity=".2"/><circle cx="600" cy="120" r="34" fill="#151513" stroke="' . $b . '" stroke-opacity=".3"/><path d="M586 120l10 10 18-20" fill="none" stroke="' . $o . '" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>';
        case 'search':
            return $head . '<circle cx="380" cy="165" r="95" fill="#151513" stroke="' . $b . '" stroke-opacity=".8" stroke-width="5"/><path d="M448 233l70 70" stroke="' . $o . '" stroke-width="14" stroke-linecap="round"/><g fill="' . $b . '" fill-opacity=".35"><rect x="330" y="120" width="100" height="12" rx="6"/><rect x="330" y="148" width="70" height="10" rx="5"/></g><g fill="' . $o . '"><rect x="330" y="182" width="100" height="14" rx="7"/></g><g fill="' . $b . '" fill-opacity=".2"><rect x="330" y="210" width="80" height="10" rx="5"/></g></svg>';
        case 'map':
            return $head . '<g fill="none" stroke="' . $b . '" stroke-opacity=".25" stroke-width="2"><path d="M150 90l130 -30 130 30 130 -30 130 30v200l-130 -30 -130 30 -130 -30 -130 30z"/><path d="M280 60v200M410 90v200M540 60v200"/></g><path d="M420 70c-42 0-72 31-72 70 0 52 72 130 72 130s72-78 72-130c0-39-30-70-72-70z" fill="' . $o . '"/><circle cx="420" cy="140" r="24" fill="#0B0B0A"/><g fill="' . $o . '"><path d="M400 205l6 12h13l-10 8 4 13-13-8-13 8 4-13-10-8h13z" transform="translate(120 -10) scale(.9)"/><path d="M400 205l6 12h13l-10 8 4 13-13-8-13 8 4-13-10-8h13z" transform="translate(170 -10) scale(.9)"/><path d="M400 205l6 12h13l-10 8 4 13-13-8-13 8 4-13-10-8h13z" transform="translate(220 -10) scale(.9)"/></g></svg>';
        case 'coins':
            return $head . '<g fill="none" stroke="' . $b . '" stroke-width="2.6"><ellipse cx="330" cy="250" rx="74" ry="24" fill="#151513"/><path d="M256 250v-36c0 13 33 24 74 24s74-11 74-24v36"/><ellipse cx="330" cy="214" rx="74" ry="24" fill="#151513"/><path d="M256 214v-36c0 13 33 24 74 24s74-11 74-24v36"/><ellipse cx="330" cy="178" rx="74" ry="24" fill="' . $o . '" stroke="' . $o . '"/></g><g fill="none" stroke="' . $b . '" stroke-opacity=".9" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M470 270l60-50 50 30 80-110"/><path d="M640 140h22v22"/></g><rect x="470" y="86" width="150" height="14" rx="7" fill="' . $b . '" fill-opacity=".25"/></svg>';
        case 'dash':
            return $head . '<rect x="170" y="48" width="500" height="264" rx="18" fill="#151513" stroke="' . $b . '" stroke-opacity=".35" stroke-width="2"/><g fill="' . $o . '"><rect x="200" y="210" width="34" height="60" rx="6" fill-opacity=".4"/><rect x="246" y="180" width="34" height="90" rx="6" fill-opacity=".6"/><rect x="292" y="150" width="34" height="120" rx="6" fill-opacity=".8"/><rect x="338" y="116" width="34" height="154" rx="6"/></g><path d="M200 130l70-30 60 20 70-40" fill="none" stroke="' . $b . '" stroke-opacity=".85" stroke-width="3" stroke-linecap="round"/><g fill="none" stroke="' . $b . '" stroke-opacity=".4" stroke-width="2"><circle cx="520" cy="130" r="42"/><path d="M520 88a42 42 0 0 1 36 62" stroke="' . $o . '" stroke-width="12"/></g><g fill="' . $b . '" fill-opacity=".3"><rect x="440" y="206" width="190" height="12" rx="6"/><rect x="440" y="232" width="140" height="12" rx="6"/><rect x="440" y="258" width="170" height="12" rx="6"/></g></svg>';
        case 'profile':
            return $head . '<rect x="320" y="20" width="200" height="320" rx="30" fill="#0B0B0A" stroke="' . $b . '" stroke-opacity=".6" stroke-width="3"/><circle cx="372" cy="86" r="26" fill="' . $o . '"/><g fill="' . $b . '" fill-opacity=".8"><rect x="412" y="68" width="80" height="10" rx="5"/></g><g fill="' . $b . '" fill-opacity=".3"><rect x="412" y="90" width="60" height="9" rx="4"/><rect x="344" y="128" width="150" height="9" rx="4"/><rect x="344" y="146" width="110" height="9" rx="4"/></g><rect x="344" y="172" width="70" height="26" rx="13" fill="' . $o . '"/><rect x="424" y="172" width="70" height="26" rx="13" fill="none" stroke="' . $b . '" stroke-opacity=".5" stroke-width="2"/><g fill="' . $b . '" fill-opacity=".18"><rect x="344" y="218" width="48" height="48" rx="8"/><rect x="396" y="218" width="48" height="48" rx="8"/><rect x="448" y="218" width="48" height="48" rx="8"/><rect x="344" y="270" width="48" height="48" rx="8"/><rect x="396" y="270" width="48" height="48" rx="8"/><rect x="448" y="270" width="48" height="48" rx="8"/></g></svg>';
        case 'kanban':
            $s = '';
            foreach ([[170, 3], [330, 2], [490, 1]] as $k => [$x, $n]) {
                $s .= '<rect x="' . $x . '" y="50" width="140" height="260" rx="14" fill="#151513" stroke="' . $b . '" stroke-opacity=".3" stroke-width="2"/>';
                for ($i = 0; $i < $n; $i++) {
                    $s .= '<rect x="' . ($x + 14) . '" y="' . (74 + $i * 70) . '" width="112" height="56" rx="10" fill="' . ($k === 2 ? $o : $b) . '" fill-opacity="' . ($k === 2 ? '.9' : '.16') . '"/><rect x="' . ($x + 26) . '" y="' . (90 + $i * 70) . '" width="60" height="8" rx="4" fill="#0B0B0A" fill-opacity=".55"/>';
                }
            }
            return $head . $s . '</svg>';
        case 'chat':
            return $head . '<rect x="290" y="20" width="260" height="320" rx="30" fill="#0B0B0A" stroke="' . $b . '" stroke-opacity=".6" stroke-width="3"/><rect x="312" y="62" width="150" height="40" rx="16" fill="' . $b . '" fill-opacity=".16"/><rect x="378" y="116" width="150" height="40" rx="16" fill="' . $o . '"/><rect x="312" y="170" width="110" height="40" rx="16" fill="' . $b . '" fill-opacity=".16"/><rect x="354" y="224" width="174" height="40" rx="16" fill="' . $o . '"/><rect x="312" y="288" width="216" height="30" rx="15" fill="none" stroke="' . $b . '" stroke-opacity=".4" stroke-width="2"/></svg>';
        case 'bot':
            return $head . '<rect x="330" y="86" width="180" height="140" rx="30" fill="#151513" stroke="' . $b . '" stroke-opacity=".8" stroke-width="4"/><circle cx="385" cy="150" r="14" fill="' . $o . '"/><circle cx="455" cy="150" r="14" fill="' . $o . '"/><path d="M390 192q30 18 60 0" fill="none" stroke="' . $b . '" stroke-width="5" stroke-linecap="round"/><path d="M420 86V56" stroke="' . $b . '" stroke-width="4" stroke-linecap="round"/><circle cx="420" cy="48" r="9" fill="' . $o . '"/><rect x="270" y="258" width="130" height="38" rx="16" fill="' . $b . '" fill-opacity=".16"/><rect x="440" y="258" width="130" height="38" rx="16" fill="' . $o . '"/></svg>';
        case 'timeline':
            return $head . '<path d="M130 190h580" stroke="' . $b . '" stroke-opacity=".4" stroke-width="4" stroke-linecap="round"/><g fill="#0B0B0A" stroke="' . $o . '" stroke-width="5"><circle cx="210" cy="190" r="20"/><circle cx="420" cy="190" r="20"/><circle cx="630" cy="190" r="20" fill="' . $o . '"/></g><g fill="' . $b . '" fill-opacity=".3"><rect x="160" y="110" width="100" height="12" rx="6"/><rect x="370" y="110" width="100" height="12" rx="6"/><rect x="580" y="110" width="100" height="12" rx="6"/><rect x="170" y="238" width="80" height="10" rx="5"/><rect x="380" y="238" width="80" height="10" rx="5"/><rect x="590" y="238" width="80" height="10" rx="5"/></g><path d="M630 150V86l46 16-46 16" fill="' . $o . '" stroke="' . $o . '" stroke-width="3" stroke-linejoin="round"/></svg>';
        case 'cards':
            return $head . '<g><rect x="250" y="70" width="240" height="150" rx="20" fill="#151513" stroke="' . $b . '" stroke-opacity=".4" stroke-width="2" transform="rotate(-8 370 145)"/><rect x="330" y="120" width="240" height="150" rx="20" fill="' . $o . '" transform="rotate(5 450 195)"/></g><g fill="#0B0B0A" fill-opacity=".85" transform="rotate(5 450 195)"><circle cx="372" cy="228" r="11"/><circle cx="404" cy="228" r="11"/><circle cx="436" cy="228" r="11"/></g><g fill="none" stroke="#0B0B0A" stroke-opacity=".55" stroke-width="3" transform="rotate(5 450 195)"><circle cx="468" cy="228" r="11"/><circle cx="500" cy="228" r="11"/></g><circle cx="610" cy="110" r="32" fill="#151513" stroke="' . $b . '" stroke-opacity=".3"/><path d="M596 110l10 10 18-20" fill="none" stroke="' . $o . '" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>';
        default: // bars
            return $head . '<g fill="none" stroke="' . $b . '" stroke-opacity=".9" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M120 300h600" stroke-opacity=".35"/><rect x="170" y="210" width="64" height="90" rx="8" fill="' . $o . '" fill-opacity=".25" stroke="' . $o . '"/><rect x="274" y="170" width="64" height="130" rx="8" fill="' . $o . '" fill-opacity=".35" stroke="' . $o . '"/><rect x="378" y="125" width="64" height="175" rx="8" fill="' . $o . '" fill-opacity=".5" stroke="' . $o . '"/><rect x="482" y="80" width="64" height="220" rx="8" fill="' . $o . '" stroke="' . $o . '"/><path d="M150 190l124-52 104 22 168-86" stroke-width="3"/></g></svg>';
    }
}
